  "insight": "互乡名声差，少年来了，弟子们奇怪，孔子却见了，理由是“与其进也，不与其退也”——他看重的是这个人此刻往上走的劲儿，不是过去的名声。“人洁己以进，与其洁也”：人家收拾干净了往前走，你就该肯定这份干净，别拿旧账钉死他。对此刻的我：给人贴“就这样了”的成见最省事，也最伤人；只要他此刻真想变好，就给他机会，别让偏见替你判断。"
