  "text": "朋友死，无所归，曰：「于我殡。朋友之馈，虽车马，非祭肉，不拜。",
  "source": "乡党篇",
  "translation": "朋友去世，没有亲人来收殓，孔子说：我来为他办理丧事。朋友送的礼物，即使是车马，如果不是分送的胙肉，他都不行拜礼。",
  "insight": "朋友死了没人收殓，孔子说“我来办”——这是朋友之义最重的一种：关键时刻，我来托底。后半句也很有分寸：朋友送再贵重的礼（车马）都不拜，只有胙肉（敬祖之物）才郑重行礼——因为他看重的是心意和敬重，不是东西值多少钱。今天交朋友，最值钱的就是这种“你出事了我在”的担当，和“我不拿你当提款机”的分寸。讲义气，也要有边界。"
